<?php
namespace App\Console\Commands;use App\Models\CheckoutPayment;use App\Services\Accounting\AccountingExportService;use Illuminate\Console\Command;
class InvoiceExpiredCheckouts extends Command{protected$signature='checkout:invoice-expired {--limit=100}';protected$description='Sender ubetalte utsjekkinger til regnskap etter 24 timer';public function handle(AccountingExportService $accounting):int{$items=CheckoutPayment::whereIn('status',['pending','processing','failed'])->whereNull('invoiced_at')->where('expires_at','<=',now())->limit((int)$this->option('limit'))->get();foreach($items as$p){$connection=$accounting->activeConnection($p->organization_id);if(!$connection){$p->update(['status'=>'failed','last_error'=>'Ingen aktiv regnskapskobling']);continue;}$invoice=$p->invoiceExport;if($invoice->status==='exported'){$p->update(['status'=>'expired','invoiced_at'=>now()]);continue;}$accounting->queue($invoice,$accounting->providerName($connection));if($accounting->processQueued($invoice))$p->update(['status'=>'expired','invoiced_at'=>now(),'last_error'=>null]);else$p->update(['status'=>'failed','last_error'=>$invoice->fresh()->last_error]);}$this->info($items->count().' utløpte betalinger behandlet.');return self::SUCCESS;}}
